<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany;
class ProfessionalCredential extends Model { use HasUuids; protected $guarded=[]; protected $hidden=['credential_number']; protected function casts():array{return ['credential_number'=>'encrypted','issued_on'=>'date','expires_on'=>'date','does_not_expire'=>'boolean','renewal_due_on'=>'date','verified_at'=>'datetime','last_status_evaluated_at'=>'datetime'];} public function member():BelongsTo{return $this->belongsTo(Member::class);} public function primaryDocument():BelongsTo{return $this->belongsTo(MemberDocument::class,'primary_document_id');} public function documents():BelongsToMany{return $this->belongsToMany(MemberDocument::class,'credential_documents','credential_id','document_id')->withPivot('purpose')->withTimestamps();} public function reminders():HasMany{return $this->hasMany(CredentialReminderEvent::class,'credential_id');} public function statusEvents():HasMany{return $this->hasMany(CredentialStatusEvent::class,'credential_id');} public function getMaskedNumberAttribute():?string{return $this->credential_number_last4 ? '••••'.$this->credential_number_last4 : null;} }
